insert into public.site_content (key, value) values
('content', '{"heroTitle":"ACHIRA","heroLead":"Un cercle qui avance ensemble.","heroEyebrow":"Des histoires singulières. Des valeurs partagées.","manifesto":"AKARBI est née d’une rencontre. ACHIRA prolonge cette possibilité : trouver, au croisement de parcours différents, des personnes avec qui partager une ambition, une sensibilité et l’envie de construire.","sidesIntro":"Un projet ne se résume pas à une idée. Il a une comptabilité, une fiscalité, une trésorerie, des contrats, une fabrication, une image. Chaque côté demande un savoir-faire, et le cercle les réunit.","quote":"L’achat donne un accès.","quoteEm":"Les valeurs donnent l’appartenance.","motto":"TRUST YOUR WAY"}'::jsonb),
('settings', '{"siteName":"ACHIRA","akarbiUrl":"","instagram":"","discord":"https://discord.gg/FdEmP3XJq"}'::jsonb) on conflict (key) do update set value = excluded.value;
